    /** Commits newly inserted files and applies only persistence metadata returned by storage. */
    async commitCreatedFiles(request: CommitRequest) {
        const { config } = this.dependencies.requireDependencies()
        const updatedFiles = await this.commitTrackingPaths(request)
        if (updatedFiles.length > 0) this.dependencies.updateFiles(updatedFiles, [], config.workingFolder)

        return updatedFiles
    }

    /** Queues a local file change for the batched commit, keeping the open document in sync. */
    saveFile(file: MarkdownFile, saveReference?: OpenDocumentSaveReference) {
        const { commitBatcher, project } = this.requireProject('save a file')
        const existingFile = this.dependencies.requireFile(file.path)
        if (existingFile.content === file.content) return existingFile

        this.replaceUpdatedFiles([file])
        commitBatcher.schedule(project.branch, [attachSaveReference(file, saveReference)], `Update ${file.path}`)
        this.dependencies.dispatchChanged()

        return file
    }

    /** Mutates one owned card and queues its reference for serialization at flush. */
    saveCardChange(
        path: string,
        mutation: (card: Card) => void,
        saveReference?: OpenDocumentSaveReference,
        message = `Update ${path}`,
    ) {
        const { commitBatcher, config, project } = this.requireProject('save a card')
        const openDocument = this.findOpenCardDocument(path)
        const card = this.mutateCardPreservingOpenBody(path, mutation, config.workingFolder)
        const cardInternalId = card.header.internalId
        if (!cardInternalId) throw new Error(`Cannot save a card without an internal ID: ${path}`)
        const documentSaveReference = saveReference ?? openDocument?.createSaveReference()

        commitBatcher.schedule(project.branch, [{ cardInternalId, path: card.path, saveReference: documentSaveReference }], message)
        this.dependencies.dispatchChanged()

        return card
    }

    async flushPendingCommits() {
        const { commitBatcher } = this.dependencies.requireDependencies()
        const hadPendingCommits = commitBatcher.hasPending()

        try {
            await commitBatcher.flush()
        } catch (error) {

        const card = dependencies.requireCard(path)
        if (getCardIdPrefix(card.header.id) === cardType.idPrefix) return markdownParsingService.serializeCard(card)

        const number = getNextCardNumber(dependencies.files(), cardType.idPrefix)
        const id = buildCardId(cardType.idPrefix, number, config.cardSeparator)
        const targetPath = cardPathForId(path, id, card.header.title, config.cardSeparator)
        this.context.requireAvailablePath(targetPath)
        return this.renameCard(path, targetPath, (currentCard) => setCardHeaderFields(currentCard, { id }), saveReference)
    }

    /** Commits pending work, then commits the rename on its own so no other change shares its batch entry. */
    private async renameCard(
        path: string,
        targetPath: string,
        mutation: (card: Card) => void,
        saveReference?: OpenDocumentSaveReference,
    ) {
        const { dependencies } = this.context
        const { commitBatcher, config, project } = this.context.requireProject('rename a card')

        await this.context.flushPendingCommits()

        const card = this.context.mutateCardPreservingOpenBody(path, mutation, config.workingFolder)
        const cardInternalId = card.header.internalId
        if (!cardInternalId) throw new Error(`Cannot rename a card without an internal ID: ${path}`)
        const documentSaveReference = saveReference ?? this.context.findOpenCardDocument(path)?.createSaveReference()
        commitBatcher.schedulePathChange(
            project.branch,
            path,
            { cardInternalId, path, saveReference: documentSaveReference, targetPath },
            `Rename ${path} to ${targetPath}`,
            (fromPath, toPath) => this.reconcileCardPath(fromPath, toPath),
        )
        dependencies.dispatchChanged()
        await this.context.flushPendingCommits()

        return markdownParsingService.serializeCard(card)
    }

    /** Moves local state onto the committed path and lets path-keyed callers follow the card. */
    private reconcileCardPath(fromPath: string, toPath: string) {

            const updatedCard = dependencies.mutateCard(
                card.path,
                (currentCard) => setCardHeaderFields(currentCard, { internalId }),
                config.workingFolder,
            )
            cardsToPersist.push(updatedCard)
        }
        if (cardsToPersist.length > 0) {
            const changes = cardsToPersist.map((card) => {
                const cardInternalId = card.header.internalId
                if (!cardInternalId) throw new Error(`Generated card identity was not applied: ${card.path}`)

                return { cardInternalId, path: card.path }
            })
            commitBatcher.schedule(project.branch, changes, 'Add missing card internal IDs')
        }
        dependencies.dispatchChanged()

        return cardsToPersist.length
    }
}

    private scheduleMarkdownReloadBatch() {
        this.clearMarkdownReloadTimeout()
        this.markdownReloadTimeout = window.setTimeout(() => {
            void this.reloadMarkdownFilesFromWatchEvents()
        }, MARKDOWN_RELOAD_DEBOUNCE_MS)
    }

    private clearMarkdownReloadTimeout() {
        if (this.markdownReloadTimeout === null) return

        window.clearTimeout(this.markdownReloadTimeout)
        this.markdownReloadTimeout = null
    }

    private clearMarkdownRemovalTimeouts() {
        this.markdownRemovalTimeoutsByPath.forEach((timeout) => window.clearTimeout(timeout))
        this.markdownRemovalTimeoutsByPath.clear()
    }

    private async reloadMarkdownFilesFromWatchEvents() {
        const { commitBatcher, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject || !storage.loadFile) return

        this.clearMarkdownReloadTimeout()
        const events = [...this.markdownReloadEventsByPath.values()]
        this.markdownReloadEventsByPath.clear()
        const updatedFiles: MarkdownFile[] = []
        const removedPaths: string[] = []

        for (const event of events) {
            if (this.dependencies.commitPathsInFlight().has(event.path)) continue
            const loadedFile = event.changeKind === 'removed' ? null : await this.loadWatchedMarkdownFile(event)
            if (loadedFile && this.dependencies.matchesCurrentContent(loadedFile.path, loadedFile.content)) continue
            const dirtyOpenDocument = openFilesService.getRegisteredDocuments().some((document) => (
                document.kind === 'card' && document.path === event.path && document.dirty
            ))
            if (commitBatcher.hasPendingFile(event.path) || dirtyOpenDocument) {
                reportMarkdownWatchConflict(event.path)
                continue
            }

            if (event.changeKind === 'removed') {
                removedPaths.push(event.path)
                continue
            }

            if (!loadedFile) {
                if (event.changeKind === 'unknown') removedPaths.push(event.path)
                continue
            }

            const currentFile = this.dependencies.files().find((file) => file.path === loadedFile.path)
            if (currentFile?.content === loadedFile.content) continue

            updatedFiles.push(loadedFile)
        }

        const removedPathSet = new Set(removedPaths)
        const watchedFiles = mergeFiles(
            this.dependencies.files().filter((file) => !removedPathSet.has(file.path)),
            updatedFiles,
        )
        const importedFiles = await this.importExternalCardFiles(watchedFiles, this.dependencies.requireDependencies().config.workingFolder)
        if (updatedFiles.length === 0 && removedPaths.length === 0 && importedFiles === watchedFiles) return

        const { config } = this.dependencies.requireDependencies()
        const currentFiles = this.dependencies.files()
        const currentFilesByPath = new Map(currentFiles.map((file) => [file.path, file]))
        const importedPaths = new Set(importedFiles.map((file) => file.path))

        service.init({ storage: githubStorage })

        await expect(service.projectLoading.openProject(githubProject)).rejects.toBeInstanceOf(GithubUnauthorizedError)
        expect(handleUnauthorized).toHaveBeenCalledTimes(1)
    })

